WITH supplier_stats AS (SELECT supplier_id, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(brand))) AS brand_values, SUM(CASE WHEN category = 'Electronics' THEN 1 ELSE 0 END) AS electronics_count FROM products GROUP BY supplier_id) SELECT s.id, s.country, s.city, ss.brand_values, ss.electronics_count FROM suppliers s INNER JOIN supplier_stats ss ON s.id = ss.supplier_id WHERE ss.electronics_count > 55 ORDER BY ss.brand_values, s.city;
